INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `VerifiedBuild`) VALUES
(2782,'zhTW','林吉的秘密','找到對這塊石板有更多瞭解的人。',0),
(2783,'zhTW','爭論','與詛咒之地和悲傷沼澤交界處的部落英雄的靈魂談話。',0),
(2784,'zhTW','失去的榮耀','聆聽部落英雄的靈魂講述他的故事。',0),
(2801,'zhTW','悲傷的故事','聆聽部落英雄的靈魂講述他的故事。',0),
(2821,'zhTW','品質的保證','給羽月要塞的普拉特·馬克格魯比帶去10張厚重的雪人皮。',0),
(2822,'zhTW','品質的保證','給莫沙徹營地的杉多爾·迅蹄帶去十張厚重的雪人皮。',0),
(2841,'zhTW','設備之戰','從諾姆瑞根拿到鑽探設備藍圖和麥克尼爾的保險箱密碼，把它們交給奧格瑪的諾格。',0),
(2842,'zhTW','首席工程師斯庫提','和藏寶海灣的斯庫提談話。',0),
(2843,'zhTW','出發!諾姆瑞根!','等斯庫提調整好哥布林傳送器。',0),
(2844,'zhTW','大保姆','尋找走丟了的精靈小姑娘。',0),
(2845,'zhTW','迷路的沙恩','從箱子裡拿取沙恩的鈴鐺，然後護送沙恩·飄葉回到羅克比特的營地。',0),
